window.RP_SESSION={"id":"S-c0a889c79856","messages":[{"id":"RP-III-0182339","time":"2026-09-18T21:02:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"의뢰에서 돌아오고 나서는, 복수에 불타며 미래를 생각하기보다는 현재를 살아가기로 했습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182340","time":"2026-09-18T21:03:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"의뢰에서 조금 긁힌 상처들을 치료하며 생각했습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182341","time":"2026-09-18T21:04:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"그래도 이번에도 크게 다치지 않은 걸 보니, 운이 매우 좋다는 것을요.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182342","time":"2026-09-18T21:04:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"뭐, 허수아비한테 죽을 뻔하긴 했지만요.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182343","time":"2026-09-18T21:05:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"치료가 끝나고 나서, 목걸이를 가볍게 쓰다듬고서 입을 맞췄습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182344","time":"2026-09-18T21:06:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"언제 죽을지도 모르는 생. 에스텔 선배가 보여준 대로, 팔이나 다리가 언제 잘릴지도 모르죠. 혹은… 목이거나.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182345","time":"2026-09-18T21:07:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"후회 없이 살아야겠죠. 마음껏 좋아하면서 살도록.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182346","time":"2026-09-18T21:07:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"시장으로 향했습니다. 부디, 찾는 장신구가 있으면 좋겠네요.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182347","time":"2026-09-18T21:07:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"……","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182348","time":"2026-09-18T21:10:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"!운명","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182349","time":"2026-09-18T21:10:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"운명 : 9 = 9\n결과 : 훌륭한 성공, 운명이 당신을 이끕니다.","characters":[]},{"id":"RP-III-0182350","time":"2026-09-18T21:11:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"이런 건 고향에서도 흔치 않았지만, 한참을 돌아다닌 끝에… 시장 한 켠 구석진 곳에 있는 점집에서 찾던 장신구를 발견할 수 있었습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182351","time":"2026-09-18T21:12:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"하긴, 부적 같은 것이니 이런 곳에 파는 게 정상이려나요? 그래도 운이 좋았습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182352","time":"2026-09-18T21:18:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"\"…이걸 구매하고 싶어요. 값은 얼마나 치르면 될까요? 부르는 값대로 살게요. 꼭, 선물해 주고픈 이가 있어서요. 부탁드릴게요.\"","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182353","time":"2026-09-18T21:18:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"!매력","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182354","time":"2026-09-18T21:18:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'Reggiano Elena'의 매력 판정 :\n[4] + [0] = [4]\n결과 : 쓰라린 실패, 운명을 빗겨갈 순 없습니다.","characters":[]},{"id":"RP-III-0182355","time":"2026-09-18T21:19:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"의뢰를 아무리 나가도, 그녀의 외모에서 티가 나는 촌티를 벗을 수는 없으니까요. 호구를 잡아 신이 난 점술가는 옳거니! 하고 값을 불렀습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182356","time":"2026-09-18T21:21:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"아주 화려한 말솜씨를 뽐내며, 무려… 40실링을 달라고 하네요.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182357","time":"2026-09-18T21:21:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"하지만 이런 걸 따질 그녀는 아니니까요. 이런 상황은 익숙하기도 하고요.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182358","time":"2026-09-18T21:23:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"값을 치르고, 그녀는 소중히 장신구를 손에 쥐고서 점집을 나갔습니다.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182359","time":"2026-09-18T21:24:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182360","time":"2026-09-18T21:24:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"비록, 원하던 상징은 아니지만요. 좋아하지 않을까요?","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182361","time":"2026-09-18T21:25:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"부디 그가 좋아하길 간절히 바라며, 기다란 숨을 내뱉었습니다. 이걸로 마음이 조금은 가벼워졌으니.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182362","time":"2026-09-18T21:26:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"길드로, 집으로 돌아갈 시간이었습니다. 당분간 이 일상을 누려야 화가 가라앉겠죠.","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182363","time":"2026-09-18T21:26:00+09:00","room":"RP III","name":"엘레나 레지아노","profile":"Reggiano Elena","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-89d5e8c6329e"]},{"id":"RP-III-0182364","time":"2026-09-18T21:26:00+09:00","room":"RP III","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"... see you again, cowboy.","characters":[]}]};
